export async function run(input, api) {
  const file = await api.workspace.readText({ path: input.path, maxBytes: 65536 });
  if (!file || typeof file.text !== 'string' || !Number.isSafeInteger(file.bytes) || file.bytes < 0) {
    throw new Error('invalid-file-result');
  }
  const parts = file.text.split(/\r\n|\n|\r/);
  const lines = file.text.length === 0 ? 0 : parts.length - (parts[parts.length - 1] === '' ? 1 : 0);
  const proposal = [
    '文件：' + input.path,
    '文本行数：' + lines + '（CRLF、LF、CR 均计为换行；文件末尾的换行符不额外增加空行）',
    '原始文件字节数：' + file.bytes + ' B',
    '这是实际文本统计，不包含模型分析。'
  ].join('\n');
  await api.draft.append({ text: proposal });
  return { path: input.path, lines, bytes: file.bytes, summary: '统计已完成，草稿尚未加入编辑区。' };
}
